// A compact editable voxel world: each block remains addressable, while rendering is batched by material.
const solidTypes=new Set(['grass','dirt','stone','sand','wood','leaves','plank']);
function saveProgress(){try{localStorage.setItem('blockhaven-save-v1',JSON.stringify({seed:worldSeed,blocks:[...blocks],inventory,placed}))}catch(_){}}
try{const saved=JSON.parse(localStorage.getItem('blockhaven-save-v1')||'null');if(saved?.blocks&&saved.blocks.length<30000){worldSeed=saved.seed||worldSeed;blocks.clear();for(const [k,v] of saved.blocks)blocks.set(k,v);Object.assign(inventory,saved.inventory||{});placed=saved.placed||0;rebuildInstances();drawBar();updateGoals()}}catch(_){/* start with the generated island */}
const raycaster=new THREE.Raycaster();raycaster.far=6;const center=new THREE.Vector2(0,0);
function targetedBlock(){camera.updateMatrixWorld();raycaster.setFromCamera(center,camera);const hit=raycaster.intersectObjects(rayTargets,false)[0];if(!hit||hit.instanceId==null)return null;const mesh=hit.object,k=mesh.userData.keys[hit.instanceId],parts=parse(k);let normal=hit.face.normal.clone().transformDirection(mesh.matrixWorld);normal.set(Math.round(normal.x),Math.round(normal.y),Math.round(normal.z));return {key:k,parts,type:blocks.get(k),normal,point:hit.point}}
function breakBlock(){if(!running)return;const hit=targetedBlock();if(!hit){notify('Nothing in reach');return}if(hit.type==='water')return;blocks.delete(hit.key);if(hit.type==='wood'){inventory.wood++;notify('Collected a piece of wood')}else if(hit.type==='dirt'||hit.type==='grass')inventory.dirt++;else if(hit.type==='stone')inventory.stone++;else if(hit.type==='plank')inventory.plank++;broken++;rebuildInstances();drawBar();updateGoals();saveProgress()}
function placeBlock(){if(!running)return;if((inventory[selected]||0)<=0){notify(`No ${selected} left`);return}const hit=targetedBlock();if(!hit){notify('Aim at a block to build');return}const [x,y,z]=hit.parts.map((v,i)=>v+Math.round([hit.normal.x,hit.normal.y,hit.normal.z][i]));const k=key(x,y,z);if(blocks.has(k)){notify('That spot is already taken');return}if(Math.abs(x-player.pos.x)<.75&&Math.abs(z-player.pos.z)<.75&&Math.abs(y-player.pos.y+0.7)<1.6){notify('Move back to place there');return}const map={dirt:'dirt',stone:'stone',wood:'wood',plank:'plank'};put(x,y,z,map[selected]||'dirt');inventory[selected]--;placed++;rebuildInstances();drawBar();updateGoals();saveProgress();if(placed===4&&inventory.wood>=5)notify('Island maker! You did it.')}
function floorHeight(x,z){let highest=-Infinity;for(let dx of [-.28,.28])for(let dz of [-.28,.28]){const bx=Math.floor(x+dx+.5),bz=Math.floor(z+dz+.5);for(let y=12;y>=-3;y--){const t=blocks.get(key(bx,y,bz));if(t&&solidTypes.has(t)){highest=Math.max(highest,y+.5);break}}}return highest}
function bodyBlocked(x,y,z){for(const dx of [-.25,.25])for(const dz of [-.25,.25])for(const ey of [y-1.48,y-.78,y-.12]){const bx=Math.floor(x+dx+.5),by=Math.floor(ey+.5),bz=Math.floor(z+dz+.5);if(solidTypes.has(blocks.get(key(bx,by,bz))))return true}return false}
function updatePlayer(dt){if(!running)return;const forward=(keysDown.has('KeyW')||keysDown.has('ArrowUp')?1:0)-(keysDown.has('KeyS')||keysDown.has('ArrowDown')?1:0)-joyVec.y;const side=(keysDown.has('KeyD')||keysDown.has('ArrowRight')?1:0)-(keysDown.has('KeyA')||keysDown.has('ArrowLeft')?1:0)+joyVec.x;const len=Math.hypot(forward,side)||1,speed=keysDown.has('ShiftLeft')?6.2:4.2;const dx=(-Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)/len*speed*dt,dz=(-Math.cos(player.yaw)*forward-Math.sin(player.yaw)*side)/len*speed*dt;const nx=player.pos.x+dx,nz=player.pos.z+dz;if(!bodyBlocked(nx,player.pos.y,player.pos.z))player.pos.x=nx;if(!bodyBlocked(player.pos.x,player.pos.y,nz))player.pos.z=nz;player.vel.y-=18*dt;let ny=player.pos.y+player.vel.y*dt;const floor=floorHeight(player.pos.x,player.pos.z);if(floor>-Infinity&&ny-1.62<=floor&&player.vel.y<0){ny=floor+1.62;player.vel.y=0;player.onGround=true}else player.onGround=false;if(bodyBlocked(player.pos.x,ny,player.pos.z)){if(player.vel.y>0)player.vel.y=0;ny=player.pos.y;player.onGround=true}player.pos.y=ny;if(player.pos.y< -6){notify('Back to shore');resetSpawn()}camera.position.copy(player.pos);camera.rotation.set(player.pitch,player.yaw,0,'YXZ')}
let elapsed=0;function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;if(running){updatePlayer(dt);dayTime+=dt;sun.position.x=Math.sin(dayTime*.025)*23-6;sun.position.y=22+Math.sin(dayTime*.025)*4;document.querySelector('#coords').textContent=`${Math.round(player.pos.x)}, ${Math.round(player.pos.z)}`;document.querySelector('#timeLabel').textContent=dayTime%120<90?'A bright morning':'Long golden afternoon'}renderer.render(scene,camera)}animate();
